use std::collections::HashMap;struct WordDistance{m:HashMap<String,Vec<i32>>}impl WordDistance{fn new(w:Vec<String>)->Self{let mut m=HashMap::new();for(i,s)in w.into_iter().enumerate(){m.entry(s).or_insert_with(Vec::new).push(i as i32);}Self{m}}fn shortest(&self,a:String,b:String)->i32{let(x,y)=(&self.m[&a],&self.m[&b]);let(mut i,mut j,mut r)=(0,0,i32::MAX);while i<x.len()&&j<y.len(){r=r.min((x[i]-y[j]).abs());if x[i]<y[j]{i+=1}else{j+=1}}r}}
